{"content": """"Decode BSK config_json (base64 -> zlib -> JSON) and dump the prompt/camera wiring."""
import json, os, zlib, base64
from PIL import Image

PANEL = r"C:\Users\UserX\AppData\Local\Comfy-Desktop\ComfyUI-Installs\ComfyUI\ComfyUI\user\default\bsk_panel\Anima_新版ComfyUI"
FILES = ["Anima_全功能_新版comfyui.png", "anima_控制_重绘_klein放大.png", "Anima_简单.png"]
BASE = r"C:\Users\UserX\.zcode\comfy-mcp\_bsk"
OUT = BASE + r"\_probe.txt"

buf = []
def w(s=""):
    buf.append(str(s))

for fn in FILES:
    im = Image.open(os.path.join(PANEL, fn))
    s = im.info.get("config_json")
    w("=" * 95)
    w(f"FILE: {fn}")
    w("=" * 95)
    try:
        raw = zlib.decompress(base64.b64decode(s))
        cfg = json.loads(raw.decode("utf-8"))
        w(f"  decoded OK: {len(raw)} bytes")
    except Exception as e:
        w(f"  decode FAIL: {e}")
        continue

    w(f"  top-level keys: {list(cfg.keys())}")
    outp = BASE + "_" + fn.replace(".png", ".json")
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(cfg, f, ensure_ascii=False, indent=1)
    w(f"  -> {outp}")

    # hunt for the graph
    def find_graph(o, path="$"):
        if isinstance(o, dict):
            if "nodes" in o and isinstance(o["nodes"], list):
                yield path, o
            for k, v in o.items():
                yield from find_graph(v, f"{path}.{k}")
        elif isinstance(o, list):
            for i, v in enumerate(o[:3]):
                yield from find_graph(v, f"{path}[{i}]")

    for path, g in find_graph(cfg):
        nodes = {n.get("id"): n for n in g["nodes"] if isinstance(n, dict)}
        w("")
        w(f"  GRAPH at {path}: {len(nodes)} nodes, links={len(g.get('links', []))}")
        links = {}
        for l in g.get("links", []) or []:
            if isinstance(l, list) and len(l) > 4:
                links[l[0]] = l
            elif isinstance(l, dict) and "id" in l:
                links[l["id"]] = [l["id"], l.get("origin_id"), l.get("origin_slot"),
                                  l.get("target_id"), l.get("target_slot"), l.get("type")]
        for nid, n in nodes.items():
            t = n.get("type")
            if t == "bsk_StringMergeWithSwitch":
                w("")
                w(f"    >>> 合并提示词  id={nid} title={n.get('title')!r}")
                w(f"        widgets_values={n.get('widgets_values')!r}")
                for inp in n.get("inputs", []) or []:
                    lk = inp.get("link")
                    nm = inp.get("name")
                    if lk is not None and lk in links:
                        l = links[lk]
                        src = nodes.get(l[1], {})
                        w(f"        {nm:9s} <- node {str(l[1]):>5}  type={src.get('type'):<30} title={src.get('title')!r}")
                    else:
                        w(f"        {nm:9s} <- (空 / 手输)")
            if t == "CameraControlNode":
                w("")
                w(f"    >>> 相机控制  id={nid} title={n.get('title')!r}")
                w(f"        widgets_values={json.dumps(n.get('widgets_values'), ensure_ascii=False)[:900]}")
            if t == "BSK_ParamSet":
                w("")
                w(f"    >>> BSK 参数集  id={nid} title={n.get('title')!r}")
                w(f"        widgets_values={json.dumps(n.get('widgets_values'), ensure_ascii=False)[:700]}")
        # consumers of merge / camera
        for nid, n in nodes.items():
            for inp in n.get("inputs", []) or []:
                lk = inp.get("link")
                if lk is not None and lk in links:
                    src = nodes.get(links[lk][1], {})
                    if src.get("type") in ("CameraControlNode", "bsk_StringMergeWithSwitch",
                                           "BSK_AIText", "BSK_Tagger"):
                        w(f"    CONSUME: [{src.get('type')}] -> node {nid} ({n.get('type')}) . {inp.get('name')}")
        w("")
        w("    -- class_type histogram --")
        hist = {}
        for n in nodes.values():
            hist[n.get("type")] = hist.get(n.get("type"), 0) + 1
        for t, c in sorted(hist.items(), key=lambda x: -x[1]):
            w(f"        {c:3d}  {t}")

with open(OUT, "w", encoding="utf-8") as f:
