{"content": """"Dump the real graph (cfg['workflow']) + the panel's cardValues for BSK Animа workflows."""
import json, os, zlib, base64
from PIL import Image

PANEL = r"C:\Users\UserX\AppData\Local\Comfy-Desktop\ComfyUI-Installs\ComfyUI\ComfyUI\user\default\bsk_panel\Anima_新版ComfyUI"
FILES = ["Anima_全功能_新版comfyui.png", "anima_控制_重绘_klein放大.png", "Anima_简单.png"]
OUT = r"C:\Users\UserX\.zcode\comfy-mcp\_bsk_probe.txt"

buf = []
def w(s=""):
    buf.append(str(s))

for fn in FILES:
    im = Image.open(os.path.join(PANEL, fn))
    cfg = json.loads(zlib.decompress(base64.b64decode(im.info["config_json"])).decode("utf-8"))
    w("#" * 100)
    w(f"# FILE: {fn}")
    w("#" * 100)

    g = cfg.get("workflow") or {}
    w(f"  workflow keys: {list(g.keys())[:15]}")
    nodes = {n.get("id"): n for n in g.get("nodes", []) if isinstance(n, dict)}
    links = {}
    for l in g.get("links", []) or []:
        if isinstance(l, list) and len(l) > 4:
            links[l[0]] = l
    w(f"  nodes={len(nodes)}  links={len(links)}")
    w(f"  currentTab={cfg.get('currentTab')!r}")
    wi = cfg.get("workflowInfo")
    w(f"  workflowInfo={json.dumps(wi, ensure_ascii=False)[:300]}")
    w(f"  tabs={json.dumps(cfg.get('tabs'), ensure_ascii=False)[:400]}")

    def title_of(nid):
        n = nodes.get(nid, {})
        return f"{n.get('type')} / {n.get('title')!r}"

    for nid, n in nodes.items():
        if n.get("type") == "bsk_StringMergeWithSwitch":
            w("")
            w(f"  >>> 合并提示词 node id={nid}  title={n.get('title')!r}")
            w(f"      widgets_values={n.get('widgets_values')!r}")
            for inp in n.get("inputs", []) or []:
                lk, nm = inp.get("link"), inp.get("name")
                if lk is not None and lk in links:
                    w(f"      {nm:9s} <- {title_of(links[lk][1])}")
                else:
                    w(f"      {nm:9s} <- 【空 / 用户手输】")

    for nid, n in nodes.items():
        if n.get("type") == "CameraControlNode":
            w("")
            w(f"  >>> 相机控制 node id={nid}  title={n.get('title')!r}")
            w(f"      widgets=[{json.dumps(n.get('widgets_values'), ensure_ascii=False)[:400]}]")
            out = n.get("outputs") or []
            w(f"      outputs={json.dumps(out, ensure_ascii=False)[:200]}")

    for nid, n in nodes.items():
        if n.get("type") == "BSK_ParamSet":
            w("")
            w(f"  >>> BSK 参数集 node id={nid}  title={n.get('title')!r}")
            w(f"      widgets={json.dumps(n.get('widgets_values'), ensure_ascii=False)[:500]}")

    w("")
    w("  -- 面板 cardValues (用户填的值, key = 节点id.输入名) --")
    cv = cfg.get("cardValues") or {}
    shown = 0
    for k, v in cv.items():
        if k.split(".")[0] in {str(i) for i in nodes}:
            if k.split(".")[-1].startswith("__"):
                continue
            s = json.dumps(v, ensure_ascii=False)
            if s in ('""', "null", "[]", "{}"):
                continue
            w(f"      {k} = {s[:220]}")
            shown += 1
            if shown > 45:
                w("      ...")
                break
    if not shown:
        w("      (全为空/默认)")

    w("")
    w("  -- 关键 class_type --")
    hist = {}
    for n in nodes.values():
        hist[n.get("type")] = hist.get(n.get("type"), 0) + 1
    for t, c in sorted(hist.items(), key=lambda x: -x[1]):
        if any(s in str(t) for s in ("bsk", "BSK", "Anima", "LanPaint", "Preprocessor",
                                     "CLIPText", "KSampler", "Lora", "Load", "VAE",
                                     "Camera", "Patch", "Control")):
            w(f"      {c:3d}  {t}")
    w("")

with open(OUT, "w", encoding="utf-8") as f:
    f.write("\n".join(buf))
print("lines:", len(buf))
