{"content": """"Dump the API-format graph (dict keyed by node id) for the BSK Anima workflows."""
import json, os, zlib, base64
from PIL import Image

PANEL = r"C:\Users\UserX\AppData\Local\Comfy-Desktop\ComfyUI-Installs\ComfyUI\ComfyUI\user\default\bsk_panel\Anima_新版ComfyUI"
TARGET = "Anima_全功能_新版comfyui.png"
OUT = r"C:\Users\UserX\.zcode\comfy-mcp\_bsk_probe.txt"

buf = []
def w(s=""):
    buf.append(str(s))

im = Image.open(os.path.join(PANEL, TARGET))
cfg = json.loads(zlib.decompress(base64.b64decode(im.info["config_json"])).decode("utf-8"))
g = cfg["workflow"]

def title(nid):
    n = g.get(str(nid)) or {}
    m = n.get("_meta") or {}
    return m.get("title") or n.get("class_type")

def ctype(nid):
    n = g.get(str(nid)) or {}
    return n.get("class_type")

w(f"FILE {TARGET}")
w(f"workflowInfo.title = {cfg['workflowInfo']['title']!r}")
w(f"node count = {len(g)}")
w("")

# index links: (targetId, inputName) -> (originId, originSlot)
w("=== full node list ===")
for nid, n in g.items():
    if not isinstance(n, dict):
        continue
    w(f"  {nid:>4}  {str(n.get('class_type')):<32} title={ (n.get('_meta') or {}).get('title')!r}")

w("")
w("=== 合并提示词 node (bsk_StringMergeWithSwitch) ===")
for nid, n in g.items():
    if not isinstance(n, dict) or n.get("class_type") != "bsk_StringMergeWithSwitch":
        continue
    w(f"  node id={nid} title={(n.get('_meta') or {}).get('title')!r}")
    for k, v in (n.get("inputs") or {}).items():
        if isinstance(v, list) and len(v) == 2:
            w(f"    {k:16s} <- LINK from node {v[0]} (slot {v[1]})  -> {ctype(v[0])} / {title(v[0])!r}")
        else:
            w(f"    {k:16s} = {json.dumps(v, ensure_ascii=False)}   【可直接手输】")

w("")
w("=== who consumes the merge output / camera output ===")
for nid, n in g.items():
    if not isinstance(n, dict):
        continue
    for k, v in (n.get("inputs") or {}).items():
        if isinstance(v, list) and len(v) == 2:
            src_t = ctype(v[0])
            if src_t in ("bsk_StringMergeWithSwitch", "CameraControlNode", "BSK_AIText", "BSK_Tagger"):
                w(f"  [{src_t}] node {v[0]} -> node {nid} ({n.get('class_type')}) . {k}")

w("")
w("=== 相机控制 (CameraControlNode) ===")
for nid, n in g.items():
    if isinstance(n, dict) and n.get("class_type") == "CameraControlNode":
        w(f"  node id={nid} title={(n.get('_meta') or {}).get('title')!r}")
        for k, v in (n.get("inputs") or {}).items():
            s = json.dumps(v, ensure_ascii=False)
            w(f"    {k:10s} = {s[:700]}")

w("")
w("=== 文本/提示词相关节点 (正文值) ===")
for nid, n in g.items():
    if not isinstance(n, dict):
        continue
    t = n.get("class_type") or ""
    if any(s in t for s in ("CLIPTextEncode", "PromptFormat", "StringMerge", "Text", "Tagger", "AIText")):
        w(f"  node {nid} [{t}] title={(n.get('_meta') or {}).get('title')!r}")
        for k, v in (n.get("inputs") or {}).items():
            if k in ("text", "string", "prompt", "input1", "input2", "input3", "input4",
                     "input5", "input6", "input7", "input8", "prefix", "suffix"):
                w(f"      {k} = {json.dumps(v, ensure_ascii=False)[:300]}")

w("")
w("=== 输入图像 / 输出 (LoadImage / SaveImage) ===")
for nid, n in g.items():
    if not isinstance(n, dict):
        continue
    t = n.get("class_type") or ""
    if "LoadImage" in t or "Save" in t or "PreviewImage" in t:
        w(f"  node {nid} [{t}] title={(n.get('_meta') or {}).get('title')!r} inputs={json.dumps(n.get('inputs'), ensure_ascii=False)[:300]}")

w("")
w("=== BSK_参数集 (BSK_ParamSet) ===")
for nid, n in g.items():
    if isinstance(n, dict) and n.get("class_type") == "BSK_ParamSet":
        w(f"  node {nid} title={(n.get('_meta') or {}).get('title')!r}")
        for k, v in (n.get("inputs") or {}).items():
            w(f"      {k} = {json.dumps(v, ensure_ascii=False)[:200]}")

w("")
w("=== 采样器 / LoRA / 模型加载 ===")
for nid, n in g.items():
    if not isinstance(n, dict):
        continue
    t = n.get("class_type") or ""
    if any(s in t for s in ("KSampler", "Lora", "UNETLoader", "CLIPLoader", "VAELoader",
                            "ModelPatchLoader", "AnimaLLLite", "Preprocessor", "LanPaint",
                            "ControlNet", "ImageScale", "Latent")):
        w(f"  node {nid} [{t}] title={(n.get('_meta') or {}).get('title')!r}")
        for k, v in (n.get("inputs") or {}).items():
            w(f"      {k} = {json.dumps(v, ensure_ascii=False)[:220]}")

with open(OUT, "w", encoding="utf-8") as f:
    f.write("\n".join(buf))
print("lines:", len(buf))
